export type LidarRamp = "Relief" | "Terrain" | "Earth" | "Greens" | "YellowRed" | "Magma" | "Gray";

// State of a library item: its operation while it runs, then a fixed result.
export type LidarResultState = "Preparing" | "Ready" | "Failed";

export type LidarSamplePointsRequest = {
	targets: LidarSampleTarget[],
	// WGS84 `[longitude, latitude]` in degrees, in the caller's order.
	points: ([number, number])[],
};

// One target's answer, in target order.
export type LidarSampleSeries =
/**
 *  One value per point, in point order; `None` where the cell declares no
 *  data or the point lies outside the generation.
 */
{ Values: { values: (number | null)[] } } | { Unavailable: { reason: LidarSampleUnavailableReason } };

// One item to sample, aimed at the generation the caller believes current.
export type LidarSampleTarget = {
	kind: LibraryItemRole,
	// Library item id, matching `kind`.
	entity_id: string,
	expected_generation_id: string,
};

// Why a sample could not produce a physical value.
export type LidarSampleUnavailableReason =
// The entity or generation no longer exists.
"MissingGeneration" |
// The head moved after the request was aimed; re-aim and try again.
"StaleGeneration" |
// The point does not transform into the generation's grid.
"TransformFailed" |
/**
 *  The item's stored data (manifest, raster or catalogue row) could not
 *  be read; asking again may succeed.
 */
"ReadFailed";

/**
 *  A Design read from a file, with the fingerprint (SHA-256 of the file's
 *  bytes) its next continuous save must still find on disk.
 */
export type LoadedDesign = {
	file: CanopiFile,
	fingerprint: string,
};

export type Locale = "en" | "fr" | "es" | "pt" | "it" | "zh" | "de" | "ja" | "ko" | "nl" | "ru";

export type MeasurementGuide = {
	id: string,
	locked?: boolean,
	start: GeoPoint,
	end: GeoPoint,
};

// Why a network request failed (contracts §2 `network.kind`).
export type NetworkFailureKind =
// No answer in time, or no progress for the stall timeout.
"timeout" |
// The host could not be reached.
"offline" |
// The server answered with an error status.
"status" |
// A redirect or a payload URL left the allowed hosts.
"host_not_allowed" |
// The payload is larger than its cap.
"too_large";

export type ObjectGroup = {
	id: string,
	locked: boolean,
	name: string | null,
	members: ObjectGroupMember[],
};

export type ObjectGroupMember = { kind: "plant"; id: string } | { kind: "zone"; id: string } | { kind: "annotation"; id: string };

/**
 *  The user action or system work a settlement belongs to: `u-` or `s-`
 *  (user or system origin) before a lowercase hyphenated uuid v4, opaque and
 *  never logged raw (2.1-M420): its `Debug` shows the origin only. A branded
 *  string in TypeScript. Rust mints the system ids of its own work; user ids
 *  arrive from the frontend's minters in 2a (2.1-M411), parsed on the way in.
 */
export type OperationId = string & { readonly __brand: "OperationId" };

export type PaginatedResult<T> = {
	items: T[],
	next_cursor: string | null,
	total_estimate: number,
};

export type PanelTarget = { kind: "placed_plant"; plant_id: string } | { kind: "species"; canonical_name: string } | { kind: "zone"; zone_id: string } | { kind: "manual" } | { kind: "none" };

/**
 *  One typed parameter value, in the units the registry declares (metres, m²,
 *  degrees). Executors convert to tool units; users never see cells.
 */
export type ParamValue = { Number: number } | { Integer: number } | { Boolean: boolean } | { Choice: string };

// What a host Open dialog answered.
export type PickOpenOutcome =
// The user closed the dialog without choosing, or its window went away.
{ kind: "cancelled" } |
// The chosen files: exactly one unless the kind allows several.
{ kind: "picked";
// Absolute paths, in the order the dialog gave them.
paths: string[] };

// What a host Save dialog answered.
export type PickSaveOutcome =
// The user closed the dialog without choosing, or its window went away.
{ kind: "cancelled" } |
// The chosen file, ending in one of the kind's extensions.
{ kind: "picked";
// The absolute path.
path: string };

export type PlacedPlant = {
	id: string,
	locked: boolean,
	canonical_name: string,
	common_name: string | null,
	color: string | null,
	symbol?: string | null,
	pinned_name?: boolean,
	position: GeoPoint,
	rotation: number | null,
	scale: number | null,
	notes: string | null,
	planted_date: string | null,
	quantity: number | null,
};

// Why the plant catalog is unavailable (Phase 1's causes, 2.1-M429).
export type PlantCatalogCause =
// No catalog file was found.
"missing" |
// The file was found but could not be opened or admitted.
"open_failed";

/**
 *  The plant catalog's state as the native plant DB handle reports it. It is
 *  not on the health wire: `SubsystemHealth[plant_catalog]` carries it as
 *  `ready` or `unavailable{plant_db_unavailable{cause}}`. It stays for the
 *  plant DB's own refusal text and the frontend's plant-DB message until
 *  those move onto the catalogue (2.1-M41).
 */
export type PlantDbStatus =
// The catalog is open.
"available" |
// No catalog file was found.
"missing" |
// The file was found but could not be opened or admitted.
"corrupt";

export type PlantLabels = "none" | "codes" | "names";

export type ProblemReportRequest = {
	description: string,
	frontend_diagnostics?: FrontendDiagnosticEntry[],
	sensitive_attachments?: ProblemReportSensitiveAttachments,
};

export type ProblemReportResult = {
	folder_path: string,
	summary_path: string,
	bundle_path: string,
	report_summary: string,
};

export type ProblemReportSensitiveAttachments = {
	current_design?: string | null,
};

/**
 *  One bounded page of a definition's processing history. The data of runs
 *  a refresh superseded is deleted; the record of the run stays.
 */
export type ProcessingHistoryPage = {
	definition_id: string,
	runs: ProcessingRun[],
	next_cursor: string | null,
};

// One run of a definition, newest first in a history page.
export type ProcessingRun = {
	job_id: string,
	state: AnalysisJobState,
	message: string | null,
	recipe_version: number,
	tool: ToolProvenance | null,
	inputs: ProvenanceInput[],
	created_at: string,
	finished_at: string | null,
	// Empty for a run that published nothing.
	outputs: ProcessingRunOutput[],
};

// One output a run published.
export type ProcessingRunOutput = {
	item_id: string,
	generation_id: string,
	coverage_cells: string | null,
};

/**
 *  What produced a derived item.
 *
 *  With a published result it describes the run that produced it; before the
 *  first result it describes the latest run's pinned inputs.
 */
export type Provenance = {
	definition_id: string,
	analysis_id: string,
	recipe_version: number,
	output_key: string,
	inputs: ProvenanceInput[],
	parameters: AnalysisParamValue[],
	// Recorded when the run published; `None` before that.
	tool: ToolProvenance | null,
	job_id: string,
	created_at: string,
};

// One input as a run pinned it.
export type ProvenanceInput = {
	key: string,
	item_id: string,
	generation_id: string,
};

/**
 *  What the samples of a raster item measure.
 *
 *  Imported sources declare one of the importable quantities; derived results
 *  carry the quantity their analysis output produces. Never inferred from a
 *  filename or a value range.
 */
export type RasterQuantity =
// Bare-earth elevation (MNT/DTM).
"GroundElevation" |
// Top surface including vegetation and buildings (MNS/DSM).
"SurfaceElevation" |
// Height relative to compatible terrain (MNH).
"AboveGroundHeight" |
// User-described continuous numeric value; numeric display only.
"OtherContinuous" |
// Terrain slope, in degrees or percent (derived only).
"Slope";

// What a Recent Design's file says about it, read when the list is shown.
export type RecentDesignPreview = { kind: "read"; plant_count: number; zone_count: number;
// `None` when the Design has no plants or zones yet.
bounds: DesignGroundBounds | null; sketch: DesignSketch | null } |
// The file is larger than previews read; the row shows its name only.
{ kind: "too_large" } |
// The file cannot be opened, and why when that is known.
{ kind: "unreadable"; reason: RecentDesignUnreadableReason };

// A Recent Design's preview, keyed by its path on the list.
export type RecentDesignSummary = {
	path: string,
	preview: RecentDesignPreview,
};

// Why a Recent Design's file cannot be opened.
export type RecentDesignUnreadableReason =
// Nothing is at the path any more: the file was moved, renamed or deleted.
"missing" |
/**
 *  A Design older than the current format (written before Canopi 2.0),
 *  which Canopi 2.0 and later do not open (ADR 0021).
 */
"older_version" |
// A Design from a newer file version than this build knows.
"newer_version" |
// The file is not a valid Design (not JSON, or not a valid document).
"damaged" |
// The file exists but could not be read (permissions, a folder, an I/O error).
"unknown";

/**
 *  Text a redactor has passed: logs, failure details and report inputs take
 *  only this type. Its field is private and its one constructor is
 *  [`Redactor::redact`]; it serialises as a plain string and is a branded
 *  string in TypeScript (2.1-M424).
 */
export type RedactedText = string & { readonly __brand: "RedactedText" };

// When a section is included.
export type ReportConsent =
// Always: the section holds no user content beyond redacted text.
"always" |
// Only when the user ticks the current Design's checkbox.
"current_design";

/**
 *  One row of `REPORT_SECTIONS`: its id, its entry in the zip, its consent and
 *  the privacy line the dialog lists (2.1-Q280).
 */
export type ReportSection = {
	// The section's id.
	id: ReportSectionId,
	// Its entry's name in the zip.
	file: string,
	// When it is included.
	consent: ReportConsent,
	// What it holds, in one English line.
	privacy: string,
};

// A section's id.
export type ReportSectionId =
// The build: app version, platform, webview or browser.
"build" |
// Each store's open status at report time, with causes.
"health" |
// Queue depths, wait times and the oldest running op.
"queues" |
// The last 50 native error settlements.
"native_settlements" |
// The frontend ring: rejected invokes and window errors.
"frontend_ring" |
// Data library job counts and recent failures.
"jobs" |
// Data library disk use and janitor state.
"library_disk" |
// The end of the app log.
"log_tail" |
// The settings summary (a hand list until 2e).
"settings_summary" |
// What the user wrote in the dialog.
"description" |
// The failure the report was opened from: its code and operation.
"originating_failure" |
// The current Design, by consent only.
"design";

