// Why a derived item is out of date. Refresh is always explicit.
export type StaleReason =
// An input item now has a different generation than the run used.
{ reason: "InputUpdated"; input_key: string; item_id: string } |
// An input item is itself out of date.
{ reason: "InputStale"; input_key: string; item_id: string } |
// The registry's recipe version moved on.
{ reason: "RecipeUpdated"; from: number; to: number } |
// A different engine build is installed.
{ reason: "ToolUpdated"; from: string; to: string };

// One store's entry in `SubsystemHealth`.
export type StoreHealth = {
	// How the store opened.
	status: StoreOpenStatus,
	// A one-time notice to show, if any.
	notice: StoreNotice | null,
};

/**
 *  The stores whose open status the app reports (contracts §11, 2.1-M429):
 *  a closed set, each later id landing with its producer (`web_user_data`
 *  with 2e and N2, `web_library` with N5).
 */
export type StoreId =
// The plant catalog.
"plant_catalog" |
// The Desktop user database.
"user_db" |
// The settings record, on both editions.
"settings" |
// The Data library catalogue.
"library_catalogue" |
// Web Drafts.
"web_drafts" |
// Web species lists (favourites, recently viewed).
"web_species_lists";

// A one-time notice about a store, cleared on dismiss (contracts §11).
export type StoreNotice =
/**
 *  The user database from before Canopi 2.0 was renamed and Canopi started
 *  fresh (ADR 0021).
 */
"moved_aside_pre_2_0" |
// Settings fields with bad values were reset.
"fields_reset" |
// A write to the store failed.
"write_failed";

/**
 *  How a store opened (contracts §11 open lifecycle). Phase 1's 1a adds the
 *  producers; `newer_read_only` is the reader release's state.
 */
export type StoreOpenStatus =
// Not opened yet.
{ kind: "opening" } |
// A migration is running.
{ kind: "migrating" } |
// Open and current.
{ kind: "ready" } |
/**
 *  An older or damaged store was rebuilt: `items` listed again, `generated`
 *  of them under a generated name.
 */
{ kind: "recovered";
// Entries listed again.
items: number;
// Entries given a generated name.
generated: number } |
// Written by a newer Canopi whose form this one reads: shown, never written.
{ kind: "newer_read_only" } |
// Written by a newer Canopi and left untouched.
{ kind: "refused_newer" } |
/**
 *  A damaged store was renamed aside and a fresh one started; `file` is the
 *  new file name only, never a path.
 */
{ kind: "set_aside_damaged";
// The set-aside file's name.
file: string } |
// The store could not be opened; `code` says why.
{ kind: "unavailable";
// Why, as a catalogue code.
code: FailureCode };

export type Story = {
	id: string,
	name: string,
	steps: StoryStep[],
};

export type StoryImage = {
	src: string,
	alt?: string,
};

export type StoryStep = {
	id: string,
	view_id: string,
	title: string,
	text?: RichTextBlock[],
	images?: StoryImage[],
};

/**
 *  Each store's open status, keyed by its id (contracts §11, 2.1-M417): the
 *  one health vocabulary the frontend shows and problem reports carry. A store
 *  the host does not open has no entry.
 */
export type SubsystemHealth = Partial<{ [key in StoreId]: StoreHealth }>;

export type Theme = "light" | "dark";

export type TimelineAction = {
	id: string,
	action_type: string,
	description: string,
	start_date: string | null,
	end_date: string | null,
	recurrence: string | null,
	targets: PanelTarget[],
	depends_on: string[] | null,
	completed: boolean,
	order: number,
};

// The engine that ran, as recorded when a run published.
export type ToolProvenance = {
	// Engine family, e.g. `geolibre`.
	engine: string,
	// The runner's own version line, e.g. `geolibre-cli 1.5.3`.
	version: string,
	// Source revision the runner was built from.
	revision: string,
	// Tool ids the run actually invoked.
	tools: string[],
};

// The architecture part of a channel key.
export type UpdateArch =
// 64-bit x86.
"x86_64" |
// 64-bit Arm.
"aarch64";

/**
 *  The installer kind Canopi was installed from: the last part of the
 *  channel file's `{os}-{arch}-{bundle}` key (2.1-M210).
 */
export type UpdateBundle =
// The Debian package.
"deb" |
// The Linux AppImage.
"appimage" |
// The Windows NSIS installer.
"nsis" |
// The Windows MSI installer.
"msi" |
// The macOS app (from the dmg).
"app";

/**
 *  What a finished download leaves: a verified payload ready to install, or
 *  only a link, when this installer cannot replace itself (no `pkexec` for a
 *  `.deb`, an AppImage in a folder Canopi cannot write, the macOS app).
 */
export type UpdateDownload =
// The payload is in memory, its signature verified.
{ kind: "verified" } |
// Nothing was downloaded; About shows the link (2.1-Q232).
{ kind: "link_only";
// The page the update is downloaded from by hand.
url: string };

// An update the channel offers this installer (contracts §3).
export type UpdateOffer = {
	// The offered version, as semver (`2.1.0`, `2.1.0-beta.2`).
	version: string,
	// The release date the channel file states, RFC 3339, when it states one.
	date: string | null,
	// The release's GitHub page, opened by About's "What's new" link (2.1-Q236).
	notes_url: string,
};

// The update operation a failure belongs to.
export type UpdateOp =
// Reading the channel file.
"updater.check" |
// Fetching and verifying the payload.
"updater.download" |
// Installing the verified payload.
"updater.install";

// The operating system part of a channel key.
export type UpdateOs =
// Linux.
"linux" |
// Windows.
"windows" |
// macOS, named `darwin` in the key as the updater names it.
"darwin";

/**
 *  How much of the update payload has arrived; sent on `update_download`'s
 *  channel, the updater's only stream (2.1-M208).
 */
export type UpdateProgress = {
	// Bytes received so far.
	received: number,
	// The payload's size when the server announced one.
	total: number | null,
};

export type Zone = {
	id: string,
	name: string | null,
	locked: boolean,
	zone_type: string,
	points: GeoPoint[],
	rotation: number,
	fill_color: string | null,
	notes: string | null,
};

